import React, { useEffect, useState } from 'react';
import DemoPopup from './DemoPopup';
import './Header.css';
import logo from '../assets/logo.png';

const Header = () => {
  const [scrolled, setScrolled] = useState(false);
  const [isDemoOpen, setIsDemoOpen] = useState(false);
  const [isHidden, setIsHidden] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };

    const handlePhoneActive = (e) => {
      setIsHidden(e.detail.active);
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('phone-scroll-active', handlePhoneActive);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('phone-scroll-active', handlePhoneActive);
    };
  }, []);

  return (
    <>
      <header className={`header ${scrolled ? 'scrolled' : ''} ${isHidden ? 'hidden-nav' : ''}`}>
        <div className="container header-content">
          <div className="logo">
            <img src={logo} alt="Driving Samaritans" className="logo-img" />
          </div>
          <nav className="nav">
            <ul className="nav-links">
              <li><a href="#mission">Mission</a></li>
              <li><a href="#features">Features</a></li>
              <li><a href="#pricing">Pricing</a></li>
            </ul>
            <button className="btn-header" onClick={() => setIsDemoOpen(true)}>Request Demo</button>
          </nav>
        </div>
      </header>
      <DemoPopup isOpen={isDemoOpen} onClose={() => setIsDemoOpen(false)} />
    </>
  );
};
export default Header;
