import React, { useState, useEffect, useRef } from 'react';
import './Features.css';
import logo from '../assets/logo.png';

// --- EDITABLE IMAGE LIST ---
import lightMap from '../assets/driver-light-map.png';
import darkMap from '../assets/driver-dark-map.png';
import activity from '../assets/activity.png';
import events from '../assets/events.png';
import screenshot from '../assets/Screenshot_20260522-170131.png';
import riderDashboard from '../assets/rider-dashboard.png';

const STEPS = [
  { 
    title: "Easy Navigation", 
    sub: "Safety First", 
    src: lightMap,
    side: "left",
    desc: "Enterprise level navigation built with safety and reliability in mind."
  },
  { 
    title: "Rider Dashboard", 
    sub: "Rider Experience", 
    src: riderDashboard,
    side: "right",
    desc: "A simplified view for members to request rides with their needs as a priority."
  },
  // { 
  //   title: "Easy Administration", 
  //   sub: "Safety for the Congregation", 
  //   src: adminReview,
  //   side: "left",
  //   desc: "Manage the users in your congregation along with reviews from riders in the community."
  // },
  { 
    title: "Easy Event Tracking",
    sub: "Connecting the Congregation",
    src: events, // Note: might be a good idea to get a screen shot with actual events filled in
    side: "left",
    desc: "Help schedule rides for upcoming services or outings."
  },
];

const Features = () => {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isPhoneVisible, setIsPhoneVisible] = useState(false);
  const [isTransparent, setIsTransparent] = useState(false);
  const featureRefs = useRef([]);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observerOptions = {
      root: null,
      threshold: 0.5,
      rootMargin: '-20% 0px -20% 0px'
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const index = featureRefs.current.indexOf(entry.target);
          if (index !== -1) {
            setActiveIndex(index);
            setIsTransparent(index === STEPS.length - 1 && entry.intersectionRatio > 0.8);
          }
        }
      });
    }, observerOptions);

    const currentRefs = featureRefs.current;
    currentRefs.forEach((ref) => {
      if (ref) observer.observe(ref);
    });

    const currentSectionRef = sectionRef.current;
    const sectionObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        setIsPhoneVisible(entry.isIntersecting);
        const event = new CustomEvent('phone-scroll-active', { 
          detail: { active: entry.isIntersecting } 
        });
        window.dispatchEvent(event);
      });
    }, { threshold: 0.1 });

    if (currentSectionRef) sectionObserver.observe(currentSectionRef);

    return () => {
      currentRefs.forEach((ref) => {
        if (ref) observer.unobserve(ref);
      });
      if (currentSectionRef) sectionObserver.unobserve(currentSectionRef);
    };
  }, []);

  return (
    <section id="features" className="features" ref={sectionRef}>
      {/* Persistent Logo during Showcase */}
      <div className={`showcase-logo ${isPhoneVisible ? 'visible' : ''}`}>
        <img src={logo} alt="Driving Samaritans" />
      </div>

      <div className="features-sticky-wrapper">
        <div className="phone-sticky">
          <div className={`phone-frame ${isPhoneVisible ? 'active' : ''} ${isTransparent ? 'transparent' : ''}`}>
            <div className="side-buttons">
              <div className="button-volume"></div>
              <div className="button-power"></div>
            </div>
            
            <div className="phone-bezel">
              <div className="punch-hole"></div>
              <div className="phone-screen">
                {STEPS.map((step, i) => (
                  <img 
                    key={i}
                    src={step.src} 
                    alt={step.title} 
                    className={`phone-image ${activeIndex === i ? 'visible' : ''}`}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="features-content">
          {STEPS.map((step, i) => (
            <div 
              key={i} 
              className={`feature-step ${activeIndex === i ? 'active' : ''} step-${step.side}`}
              ref={el => featureRefs.current[i] = el}
            >
              <div className="step-text-box">
                <span className="feature-sub">{step.sub}</span>
                <h3>{step.title}</h3>
                <p>{step.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="cross-placeholder" style={{ position: 'absolute', bottom: '0', height: '10px' }}></div>
    </section>
  );
};

export default Features;
